!function(){"use strict";document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll('a[href^="#"]').forEach(function(t){t.addEventListener("click",function(t){const e=this.getAttribute("href");if("#"===e||"#!"===e)return;const o=document.querySelector(e);if(o){t.preventDefault();const e=80,n=o.getBoundingClientRect().top+window.pageYOffset-e;window.scrollTo({top:n,behavior:"smooth"})}})}),window.addEventListener("popstate",function(){if(window.location.hash){const t=document.querySelector(window.location.hash);t&&setTimeout(function(){t.scrollIntoView({behavior:"smooth"})},100)}})})}();